# Assuming this part is in the function that handles JSON updates with CASE/WHEN
class JSONSetExpression(Func):
    function = 'JSON_SET'

    def as_sql(self, compiler, connection, **extra_context):
        # Use the existing JSON handling logic to ensure correct evaluation
        key_expression, value_expression = self.get_source_expressions()
        key_sql, key_params = compiler.compile(key_expression)
        value_sql, value_params = compiler.compile(value_expression)
        # Ensure that the key is always updated correctly even if it starts as null
        return ('JSON_SET(COALESCE({}, JSON_OBJECT()), {}, {})'.format(
            self.json_field, key_sql, value_sql
        ), key_params + value_params)
